data.arguments:
{"content": ":root {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-alt: #f8fafc;
  --border: #e4e8ee;
  --border-strong: #cbd2dc;
  --text: #0f172a;
  --text-muted: #64748b;
  --accent: #1d4ed8;
  --accent-strong: #1e3a8a;
  --accent-soft: #eef2ff;
  --danger: #b91c1c;
  --danger-soft: #fef2f2;
  --success: #047857;
  --success-soft: #ecfdf5;
  --warning: #b45309;
  --warning-soft: #fffbeb;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 12px 32px -18px rgba(15, 23, 42, 0.35);
  --shadow-lg: 0 28px 70px -28px rgba(15, 23, 42, 0.5);
  --radius: 12px;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family:
    "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial,
    sans-serif;
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
p {
  margin: 0;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

code,
.mono {
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.92em;
}

.muted {
  color: var(--text-muted);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.app-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ------------------------------------------------------------------ top bar */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 14px 28px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: linear-gradient(145deg, #2563eb, #1e40af);
  color: #fff;
  font-weight: 700;
  font-size: 18px;
  box-shadow: var(--shadow-sm);
}

.brand h1 {
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.brand p {
  font-size: 12px;
  color: var(--text-muted);
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.tenant-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface-alt);
  font-size: 12.5px;
}

.tenant-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--success);
  box-shadow: 0 0 0 3px rgba(4, 120, 87, 0.12);
}

.actor-picker {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-muted);
}

.actor-picker select {
  height: 34px;
  padding: 0 10px;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  background: var(--surface);
  font-size: 13px;
  font-weight: 550;
  color: var(--text);
}

/* ------------------------------------------------------------------- layout */

.content {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 26px 24px 72px;
}

.page-heading {
  margin-bottom: 16px;
}

.page-heading h2 {
  font-size: 22px;
  font-weight: 650;
  letter-spacing: -0.02em;
}

.page-heading p {
  margin-top: 3px;
  font-size: 13.5px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

/* ------------------------------------------------------------------ toolbar */

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
}

.search-field {
  position: relative;
  flex: 1 1 300px;
  max-width: 420px;
  display: flex;
  align-items: center;
}

.search-field input {
  width: 100%;
  height: 38px;
  padding: 0 34px 0 34px;
  border: 1px solid var(--border-strong);
  border-radius: 9px;
  background: var(--surface);
  font-size: 13.5px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.14);
}

.search-icon {
  position: absolute;
  left: 11px;
  font-size: 17px;
  color: var(--text-muted);
  pointer-events: none;
  transform: translateY(-1px);
}

.search-clear {
  position: absolute;
  right: 6px;
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
}

.search-clear:hover {
  background: var(--surface-alt);
  color: var(--text);
}

.toolbar-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.result-count {
  font-size: 12.5px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  min-width: 92px;
  text-align: right;
}

.page-size {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted);
}

.page-size select {
  height: 34px;
  padding: 0 6px;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  background: var(--surface);
  font-size: 13px;
}

/* ------------------------------------------------------------------ buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 9px;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  box-shadow: 0 1px 2px rgba(29, 78, 216, 0.35);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
}

.btn-secondary {
  background: var(--surface);
  border-color: var(--border-strong);
  color: var(--text);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-alt);
}

.btn-ghost {
  background: transparent;
  color: var(--text-muted);
}

.btn-ghost:hover:not(:disabled) {
  background: var(--surface-alt);
  color: var(--text);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover:not(:disabled) {
  background: #991b1b;
}

.icon-button {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--text-muted);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.icon-button:hover:not(:disabled) {
  background: var(--surface-alt);
  color: var(--text);
}

.link-button {
  border: 0;
  background: transparent;
  color: var(--accent);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 6px;
}

.link-button:hover {
  background: var(--accent-soft);
}

/* -------------------------------------------------------------------- table */

.table-wrap {
  overflow-x: auto;
}

.cert-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 820px;
}

.cert-table th {
  padding: 0;
  background: var(--surface-alt);
  border-bottom: 1px solid var(--border);
  text-align: left;
  white-space: nowrap;
}

.cert-table th > .sort-button {
  width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 11px 16px;
  border: 0;
  background: transparent;
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  cursor: pointer;
  text-align: left;
}

.cert-table th > .sort-button:hover,
.cert-table th > .sort-button.is-active {
  color: var(--text);
}

.cert-table th:last-child,
.cert-table th:nth-last-child(2) {
  padding: 11px 16px;
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.cert-table th:nth-last-child(2) {
  padding-left: 16px;
}

.sort-indicator {
  color: var(--border-strong);
  font-size: 10px;
}

.sort-button.is-active .sort-indicator {
  color: var(--accent);
}

.cert-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}

.cert-table tbody tr:last-child td {
  border-bottom: 0;
}

.row-clickable {
  cursor: pointer;
  transition: background 0.12s ease;
}

.row-clickable:hover {
  background: #f8faff;
}

.row-clickable:focus-visible {
  outline-offset: -2px;
}

.cell-serial {
  font-size: 12.5px;
  color: var(--text-muted);
  white-space: nowrap;
}

.cell-learner {
  font-weight: 550;
}

.cell-issued {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.cell-actions {
  text-align: right;
  width: 64px;
}

/* --------------------------------------------------------------------- badges */

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.badge-active {
  background: var(--success-soft);
  border-color: #b7e4d3;
  color: var(--success);
}

.badge-revoked {
  background: #f1f5f9;
  border-color: var(--border-strong);
  color: #475569;
}

.badge-outcome-issued {
  background: var(--success-soft);
  border-color: #b7e4d3;
  color: var(--success);
}

.badge-outcome-skipped {
  background: var(--warning-soft);
  border-color: #f3d9a4;
  color: var(--warning);
}

.badge-outcome-failed {
  background: var(--danger-soft);
  border-color: #f5c2c2;
  color: var(--danger);
}

/* --------------------------------------------------------------------- states */

.table-state {
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 52px 24px;
  text-align: center;
}

.table-state-title {
  font-size: 14.5px;
  font-weight: 600;
}

.skeleton-row td {
  padding: 14px 16px;
}

.skeleton-line {
  display: block;
  height: 10px;
  border-radius: 5px;
  background: linear-gradient(90deg, #eef1f5 25%, #f7f9fb 50%, #eef1f5 75%);
  background-size: 200% 100%;
  animation: shimmer 1.4s ease-in-out infinite;
}

.skeleton-row td:nth-child(1) .skeleton-line,
.skeleton-row td:nth-child(3) .skeleton-line {
  max-width: 120px;
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* ------------------------------------------------------------------ pagination */

.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px 16px;
  border-top: 1px solid var(--border);
}

.pagination-summary {
  font-size: 12.5px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.pagination-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

.page-button {
  min-width: 32px;
  height: 32px;
  padding: 0 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font-size: 13px;
  cursor: pointer;
}

.page-button:hover:not(:disabled) {
  background: var(--surface-alt);
  border-color: var(--border-strong);
}

.page-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.page-button.is-current {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  font-weight: 600;
}

/* --------------------------------------------------------------------- banner */

.banner {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 9px;
  font-size: 13.5px;
}

.banner-error {
  background: var(--danger-soft);
  border-color: #f5c2c2;
  color: #7f1d1d;
}

.banner-success {
  background: var(--success-soft);
  border-color: #b7e4d3;
  color: #065f46;
}

.banner-info {
  background: var(--accent-soft);
  border-color: #c7d2fe;
  color: #1e3a8a;
}

.banner-close {
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
  opacity: 0.7;
}

.banner-close:hover {
  opacity: 1;
}

/* ------------------------------------------------------------------- drawer */

.drawer-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.34);
  animation: fade-in 0.16s ease-out;
}

.drawer {
  width: min(540px, 100%);
  height: 100%;
  overflow-y: auto;
  background: var(--surface);
  box-shadow: var(--shadow-lg);
  animation: slide-in 0.2s ease-out;
}

.drawer-header {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 22px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.eyebrow {
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 3px;
}

.drawer-header h2 {
  font-size: 17px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.drawer-body {
  padding: 20px 22px 40px;
}

.drawer-skeleton {
  display: grid;
  gap: 14px;
  padding-top: 6px;
}

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px 20px;
  margin: 0 0 26px;
}

.detail-grid dt {
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.detail-grid dd {
  margin: 4px 0 0;
  font-size: 14px;
  overflow-wrap: anywhere;
}

.detail-section {
  border-top: 1px solid var(--border);
  padding-top: 18px;
  margin-top: 18px;
}

.detail-section h3 {
  font-size: 13px;
  font-weight: 650;
  letter-spacing: 0.02em;
  margin-bottom: 12px;
}

.timeline {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 16px;
}

.timeline li {
  display: grid;
  grid-template-columns: 10px 1fr;
  gap: 10px;
}

.timeline-dot {
  width: 9px;
  height: 9px;
  margin-top: 6px;
  border-radius: 50%;
  border: 2px solid var(--surface);
  box-shadow: 0 0 0 1px currentColor;
}

.timeline-issued {
  color: var(--success);
  background: var(--success);
}

.timeline-revoked {
  color: var(--danger);
  background: var(--danger);
}

.timeline-title {
  font-size: 13.5px;
  font-weight: 600;
}

.timeline-time {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.timeline-note {
  font-size: 12.5px;
  color: var(--text-muted);
  margin-top: 2px;
}

.revoke-section .btn-danger {
  margin-top: 2px;
}

.confirm-box {
  border: 1px solid #f5c2c2;
  background: var(--danger-soft);
  border-radius: 10px;
  padding: 14px;
  display: grid;
  gap: 12px;
}

.confirm-box p {
  font-size: 13.5px;
}

.confirm-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* --------------------------------------------------------------------- modal */

.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.4);
  animation: fade-in 0.16s ease-out;
  overflow-y: auto;
}

.modal {
  width: min(760px, 100%);
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  background: var(--surface);
  border-radius: 14px;
  box-shadow: var(--shadow-lg);
  animation: pop-in 0.18s ease-out;
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--border);
}

.modal-header h2 {
  font-size: 18px;
  font-weight: 650;
  letter-spacing: -0.015em;
}

.modal-body {
  padding: 20px 24px 24px;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}

.bulk-form {
  display: grid;
  gap: 16px;
}

.field {
  display: grid;
  gap: 6px;
}

.field > span {
  font-size: 12px;
  font-weight: 650;
  color: var(--text-muted);
}

.field select,
.field textarea,
.field input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--border-strong);
  border-radius: 9px;
  background: var(--surface);
  font-size: 13.5px;
}

.field select {
  height: 38px;
  padding: 0 10px;
}

.field select:focus,
.field textarea:focus,
.field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.14);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.stat {
  display: grid;
  gap: 2px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-alt);
}

.stat-value {
  font-size: 20px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.stat-label {
  font-size: 11.5px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hint {
  font-size: 12.5px;
  color: var(--text-muted);
  line-height: 1.55;
}

.hint code {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 1px 5px;
}

/* ----------------------------------------------------------------- bulk result */

.bulk-result {
  display: grid;
  gap: 14px;
}

.summary-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 4px 11px;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 12.5px;
  font-weight: 600;
  background: var(--surface-alt);
}

.chip-issued {
  background: var(--success-soft);
  border-color: #b7e4d3;
  color: var(--success);
}

.chip-skipped {
  background: var(--warning-soft);
  border-color: #f3d9a4;
  color: var(--warning);
}

.chip-failed {
  background: var(--danger-soft);
  border-color: #f5c2c2;
  color: var(--danger);
}

.chip-total {
  color: var(--text-muted);
}

.outcome-table-wrap {
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: auto;
  max-height: 340px;
}

.outcome-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.outcome-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 9px 14px;
  background: var(--surface-alt);
  border-bottom: 1px solid var(--border);
  text-align: left;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.outcome-table td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--border);
}

.outcome-table tr:last-child td {
  border-bottom: 0;
}

/* ---------------------------------------------------------------------- toast */

.toast {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 70;
  max-width: min(460px, calc(100vw - 48px));
  padding: 12px 16px;
  border-radius: 10px;
  background: #0f172a;
  color: #f8fafc;
  font-size: 13.5px;
  box-shadow: var(--shadow-md);
  animation: pop-in 0.18s ease-out;
}

.toast-error {
  background: #7f1d1d;
}

.toast-success {
  background: #064e3b;
}

/* ----------------------------------------------------------------- animations */

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slide-in {
  from {
    transform: translateX(24px);
    opacity: 0.6;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes pop-in {
  from {
    transform: translateY(8px) scale(0.985);
    opacity: 0;
  }
  to {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

/* ----------------------------------------------------------------- responsive */

@media (max-width: 860px) {
  .topbar {
    padding: 12px 16px;
  }

  .content {
    padding: 20px 14px 56px;
  }

  .toolbar {
    padding: 12px;
  }

  .search-field {
    flex-basis: 100%;
    max-width: none;
  }

  .toolbar-right {
    width: 100%;
    justify-content: flex-end;
  }

  .result-count {
    margin-right: auto;
    text-align: left;
  }

  .detail-grid {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .drawer {
    width: 100%;
  }
}
