import sqlite3, time
conn = sqlite3.connect("data/scale-1m.db")
conn.row_factory = sqlite3.Row
tenant="tenant_east"
horizon_seq = conn.execute("select max(seq) from certificates where tenant_id=?", (tenant,)).fetchone()[0]
horizon_rowid = conn.execute("select max(rowid) from certificates where tenant_id=?", (tenant,)).fetchone()[0]
select = "SELECT c.id, c.learner_name FROM certificates c WHERE c.tenant_id = ? "
order  = " ORDER BY c.learner_name COLLATE NOCASE ASC, c.id ASC LIMIT 2000"

def bench(label, where, build_params):
    t0=time.perf_counter(); last=None; total=0
    while True:
        sql = select + "AND " + where + order
        params = [tenant] + build_params(last)
        rows = conn.execute(sql, params).fetchall()
        if not rows: break
        total += len(rows)
        last = (rows[-1]["learner_name"], rows[-1]["id"])
    print(f"{label}: {time.perf_counter()-t0:.2f}s rows={total}")

or_clause = "((c.learner_name COLLATE NOCASE) > ? OR ((c.learner_name COLLATE NOCASE) = ? AND c.id > ?))"
rv_clause = "(c.learner_name COLLATE NOCASE, c.id) > (?, ?)"

def p_or(last):
    return [last[0], last[0], last[1]] if last else ["", "", ""]
def p_rv(last):
    return [last[0], last[1]] if last else ["", ""]
def p_or_seq(last):
    return [horizon_seq] + p_or(last)
def p_rv_seq(last):
    return [horizon_seq] + p_rv(last)
def p_rv_rowid(last):
    return [horizon_rowid] + p_rv(last)

bench("A OR + seq (current)", "c.seq <= ? AND " + or_clause, lambda last: [horizon_seq] + p_or(last))
bench("B rowvalue + seq", "c.seq <= ? AND " + rv_clause, p_rv_seq)
bench("C rowvalue + seq + INDEXED BY", "c.seq <= ? AND " + rv_clause + " INDEXED BY idx_cert_tenant_learner" if False else "PLACEHOLDER", p_rv_seq) if False else None
bench("D OR + seq + INDEXED BY", "c.seq <= ? AND " + or_clause, p_or_seq)
PY", "description": "Benchmark keyset variants over 50 batches", "timeoutMs": 600000}

